<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/helpers.php';require_once __DIR__.'/includes/auth.php';$db=db();$id=(int)($_GET['proposal_id']??0);$s=$db->prepare("SELECT p.*,l.name client_name,l.email client_email FROM proposals p JOIN leads l ON l.id=p.lead_id WHERE p.id=? AND p.status='accepted' LIMIT 1");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Accepted proposal not found.');}$existing=$db->prepare('SELECT id,invoice_number FROM invoices WHERE proposal_id=? LIMIT 1');$existing->execute([$id]);if($row=$existing->fetch()){header('Location: invoice-view.php?token='.urlencode((string)$db->query('SELECT public_token FROM invoices WHERE id='.(int)$row['id'])->fetchColumn()));exit;}$c=$db->prepare('SELECT id,lead_id FROM clients WHERE lead_id=? OR (email IS NOT NULL AND email=?) ORDER BY lead_id=? DESC,id LIMIT 1');$c->execute([(int)$p['lead_id'],(string)$p['client_email'],(int)$p['lead_id']]);$client=$c->fetch();if(!$client){http_response_code(409);exit('No client record is linked to this proposal lead. Create/convert the lead to a client first.');}$items=$db->prepare('SELECT description,quantity,unit_price,amount,sort_order FROM proposal_items WHERE proposal_id=? ORDER BY sort_order,id');$items->execute([$id]);$rows=$items->fetchAll();if(!$rows){http_response_code(409);exit('Accepted proposal has no line items.');}$token=bin2hex(random_bytes(32));$number='DWS-INV-'.date('Ym').'-'.str_pad((string)((int)$db->query("SELECT COUNT(*) FROM invoices WHERE DATE_FORMAT(created_at,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')")->fetchColumn()+1),4,'0',STR_PAD_LEFT);$total=(float)$p['total'];$db->beginTransaction();try{$q=$db->prepare('INSERT INTO invoices(client_id,lead_id,proposal_id,invoice_number,public_token,title,currency,subtotal,discount,tax,tax_rate,tax_amount,total,amount_paid,balance_due,status,issue_date,due_date,notes,terms) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$taxRate=(float)$p['subtotal']>0?round(((float)$p['tax']/max(1,(float)$p['subtotal']-(float)$p['discount']))*100,3):0;$q->execute([(int)$client['id'],(int)$p['lead_id'],(int)$p['id'],$number,$token,$p['title'],$p['currency'],$p['subtotal'],$p['discount'],$p['tax'],$taxRate,$p['tax'],$total,0,$total,'sent',date('Y-m-d'),date('Y-m-d',strtotime('+14 days')),$p['notes'],$p['terms']]);$invoiceId=(int)$db->lastInsertId();$iq=$db->prepare('INSERT INTO invoice_items(invoice_id,description,quantity,unit_price,line_total,amount,sort_order) VALUES(?,?,?,?,?,?,?)');foreach($rows as $r)$iq->execute([$invoiceId,$r['description'],$r['quantity'],$r['unit_price'],$r['amount'],$r['amount'],$r['sort_order']]);if($db->query("SHOW TABLES LIKE 'invoice_events'")->fetch())$db->prepare('INSERT INTO invoice_events(invoice_id,event_type,description) VALUES(?,?,?)')->execute([$invoiceId,'created','Invoice created from accepted proposal '.$p['proposal_number']]);if($db->query("SHOW TABLES LIKE 'lead_activities'")->fetch())$db->prepare('INSERT INTO lead_activities(lead_id,activity_type,subject,description) VALUES(?,?,?,?)')->execute([(int)$p['lead_id'],'invoice','Invoice '.$number.' created','Invoice generated from accepted proposal.']);$db->commit();header('Location: invoice-view.php?token='.urlencode($token));exit;}catch(Throwable $e){$db->rollBack();http_response_code(500);exit('Unable to create invoice.');}